const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".wk{box-sizing:border-box;width:100%;height:100%;min-height:0;min-width:0;padding:10px;display:grid;gap:6px;\n  grid-template-columns:minmax(0,1fr);grid-template-rows:auto auto minmax(0,1fr) auto;\n  grid-template-areas:\"hd\" \"tabs\" \"body\" \"ft\";\n  font-family:system-ui,-apple-system,\"PingFang SC\",\"Microsoft YaHei\",sans-serif;font-size:13px;line-height:1.35;\n  color:var(--ink);overflow:hidden}\n.wk.form{grid-template-rows:auto minmax(0,1fr) auto;grid-template-areas:\"hd\" \"body\" \"ft\"}\n.wk button,.wk input{font-family:inherit}\n.hd{grid-area:hd;display:flex;align-items:center;gap:4px;min-height:28px;min-width:0}\n.tabs{grid-area:tabs;display:flex;gap:4px;min-width:0}\n.body{grid-area:body;min-height:0;min-width:0;overflow:auto;display:flex;flex-direction:column;gap:5px;scrollbar-width:thin}\n.body>*{flex:none}\n.ft{grid-area:ft;display:flex;flex-wrap:wrap;gap:6px;min-width:0}\n.ft .err{flex:0 0 100%}\n\n.nb{width:28px;height:28px;flex:none;padding:0;border:1px solid var(--line);border-radius:9px;background:var(--panel-paper);\n  color:var(--ink);font-size:17px;line-height:1;cursor:pointer}\n.lab{flex:1;min-width:0;padding:0;border:0;background:none;color:var(--ink);font-size:13px;font-weight:700;\n  text-align:center;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.hd span.lab{text-align:left}\n.lab em{font-style:normal;font-size:10px;font-weight:500;color:var(--muted);margin-left:5px}\nbutton.lab{cursor:pointer}\n\n.tab{flex:1;min-width:0;height:28px;padding:0 2px;border:1px solid var(--line);border-radius:9px;background:transparent;\n  color:var(--muted);font-size:12px;font-weight:600;cursor:pointer;white-space:nowrap}\n.tab.on{background:var(--accent);border-color:transparent;color:var(--on-accent)}\n.cnt{font-style:normal;font-size:10px;margin-left:3px;opacity:.85}\n\n.row{display:flex;align-items:center;gap:8px;width:100%;box-sizing:border-box;padding:7px 9px;text-align:left;\n  color:var(--ink);background:var(--panel-paper);border:1px solid var(--line);border-radius:10px;font-size:inherit;cursor:pointer}\n.row.rdy{align-items:flex-start}\n.mk{width:18px;height:18px;flex:none;border-radius:50%;border:1.5px solid var(--muted);display:grid;place-items:center;\n  font-size:11px;color:var(--muted);line-height:1}\n.mk.on{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}\n.rl{flex:none;font-weight:700;min-width:30px}\n.rt{flex:1;min-width:0;color:var(--muted);font-size:12px;overflow-wrap:anywhere}\n.row.mrow{display:grid;grid-template-columns:auto minmax(0,1fr);column-gap:8px;align-items:start}\n.row.cf{flex-wrap:wrap;gap:2px 8px;cursor:default}\n.row.av{align-items:center}\n.wdn{flex:none;width:32px}\n.wt{flex:1;min-width:0;font-size:12px;overflow-wrap:anywhere}\n.wm{flex:none;font-size:11px;color:var(--muted);white-space:nowrap}\n\n.it{display:flex;align-items:flex-start;gap:7px;box-sizing:border-box;padding:6px 8px;background:var(--panel-paper);\n  border:1px solid var(--line);border-radius:10px}\n.it.mt{background:transparent;border-style:dashed;color:var(--muted)}\n.it.lock{border-color:var(--accent)}\n.it.bad{border-color:var(--ink)}\n.it.dn .tt{text-decoration:line-through;color:var(--muted)}\n.ck{width:18px;height:18px;margin:1px 0 0;flex:none;accent-color:var(--accent);cursor:pointer}\n.lk{width:18px;flex:none;text-align:center;font-weight:700;color:var(--accent);line-height:1.35}\n.it.mt .lk{color:var(--muted)}\n.itb,.row.mrow{font-size:inherit}\n.itb{flex:1;min-width:0;display:grid;grid-template-columns:auto minmax(0,1fr);column-gap:8px;row-gap:1px;text-align:left;\n  padding:0;border:0;background:none;color:inherit;cursor:pointer}\n.it.mt .itb{cursor:default}\n.tm{grid-column:1;font-variant-numeric:tabular-nums;font-weight:650;white-space:nowrap}\n.tt{grid-column:2;min-width:0;overflow-wrap:anywhere}\n.sb{grid-column:1/-1;display:flex;flex-wrap:wrap;align-items:center;gap:3px 5px;font-size:11px;color:var(--muted)}\n\n.dayh{display:flex;align-items:center;gap:6px;margin-top:3px;font-size:12px;color:var(--muted)}\n.dayh b{color:var(--ink)}\n.dayh.now b{color:var(--accent)}\n.tag{display:inline-block;padding:0 6px;border-radius:99px;background:var(--soft);color:var(--ink);font-size:10px;font-weight:600;line-height:1.55}\n.tag.ok{background:var(--accent);color:var(--on-accent)}\n.tag.warn{background:transparent;border:1px solid var(--ink)}\n.sum{display:flex;align-items:center;justify-content:space-between;gap:6px;font-size:12px;color:var(--muted)}\n.lnk{padding:2px;border:0;background:none;color:var(--accent);font-size:inherit;text-decoration:underline;cursor:pointer;white-space:nowrap}\n.hint{margin:2px 0;color:var(--muted);font-size:12px}\n.note,.ban{box-sizing:border-box;padding:7px 9px;border-radius:10px;background:var(--soft);font-size:12px}\n.note{display:flex;align-items:center;justify-content:space-between;gap:8px}\n.ban .bh{display:flex;align-items:center;gap:6px}\n.ban p{margin:3px 0 6px}\n.unp{display:flex;flex-direction:column;gap:2px;padding:7px 9px;border:1px dashed var(--muted);border-radius:10px;font-size:12px}\n.ur{color:var(--muted);overflow-wrap:anywhere}\n.strip{display:none;align-items:flex-end;gap:5px;padding:2px 2px 0}\n.sd{flex:1;min-width:0;display:flex;flex-direction:column;align-items:center;gap:1px}\n.bar{width:100%;height:32px;display:flex;align-items:flex-end;overflow:hidden;border-radius:6px;background:var(--soft)}\n.bar i{display:block;width:100%;background:var(--accent)}\n.sdn{font-size:11px;color:var(--muted)}\n.sd.now .sdn{color:var(--accent);font-weight:700}\n.sdm{font-size:10px;color:var(--muted)}\n\n.btn{flex:1 1 auto;min-width:0;height:32px;padding:0 10px;border:1px solid var(--line);border-radius:10px;\n  background:var(--button-paper,var(--panel-paper));color:var(--ink);font-size:12.5px;font-weight:600;cursor:pointer;\n  white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.btn.pri{background:var(--accent);border-color:transparent;color:var(--on-accent)}\n.btn.sm{flex:none;height:auto;min-height:26px;padding:4px 10px;font-size:12px;line-height:1.25;white-space:normal}\n.btn.dng{border:2px solid var(--ink)}\n.btn:disabled{opacity:.45;cursor:default}\n.btn:not(.pri):not(.sm){flex:0 1 auto;min-width:58px}\n.ft .btn.pri{flex:1 1 0}\n.wk button:focus-visible,.wk input:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n\n.fd{display:flex;flex-direction:column;gap:3px;min-width:0}\n.lb{font-size:11px;color:var(--muted)}\n.in{box-sizing:border-box;width:100%;min-width:0;height:32px;padding:0 8px;border:1px solid var(--line);border-radius:8px;\n  background:var(--panel-paper);color:var(--ink);font-size:13px}\n.pair{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:6px;min-width:0}\n.win{display:flex;align-items:center;gap:6px}\n.win .pair{flex:1}\n.chips{display:flex;flex-wrap:wrap;gap:4px}\n.chip{height:26px;padding:0 9px;border:1px solid var(--line);border-radius:99px;background:var(--panel-paper);color:var(--ink);\n  font-size:12px;cursor:pointer}\n.seg{display:flex;overflow:hidden;border:1px solid var(--line);border-radius:9px}\n.sg{flex:1;height:30px;border:0;background:var(--panel-paper);color:var(--ink);font-size:12.5px;cursor:pointer}\n.sg.on{background:var(--accent);color:var(--on-accent);font-weight:700}\n.cp{display:flex;flex-wrap:wrap;gap:6px}\n.cp .btn{flex:1 1 100%}\n.it2{display:flex;align-items:center;gap:6px;flex-wrap:wrap}\n.it2 b{min-width:0;overflow-wrap:anywhere}\n.err{padding:5px 8px;border:1px solid var(--ink);border-radius:8px;font-size:12px;font-weight:600;overflow-wrap:anywhere}\n\n/* 194x194 */\n.card[data-size=\"3x3\"] .wk{padding:8px;gap:5px;font-size:12px}\n.card[data-size=\"3x3\"] .hd{min-height:26px}\n.card[data-size=\"3x3\"] .nb{width:26px;height:26px}\n.card[data-size=\"3x3\"] .tab{height:26px;font-size:11.5px}\n.card[data-size=\"3x3\"] .cnt{display:none}\n.card[data-size=\"3x3\"] .btn{height:30px;font-size:12px}\n.card[data-size=\"3x3\"] .row{padding:5px 7px}\n.card[data-size=\"3x3\"] .it{padding:5px 7px}\n.card[data-size=\"3x3\"] .note,.card[data-size=\"3x3\"] .ban{font-size:11px;padding:6px 8px}\n.card[data-size=\"3x3\"] .hint{font-size:11px}\n\n/* narrow columns */\n.card[data-size^=\"3\"] .itb{grid-template-columns:minmax(0,1fr)}\n.card[data-size^=\"3\"] .tm,.card[data-size^=\"3\"] .tt{grid-column:1}\n.card[data-size^=\"3\"] .row.mrow{grid-template-columns:minmax(0,1fr)}\n.card[data-size^=\"3\"] .pair{grid-template-columns:minmax(0,1fr)}\n.card[data-size^=\"3\"] .win{flex-direction:column;align-items:stretch}\n.card[data-size^=\"3\"] .win .btn.sm{align-self:flex-end}\n.card[data-size^=\"3\"] .rt{flex-basis:100%}\n.card[data-size^=\"3\"] .row.rdy{flex-wrap:wrap}\n\n/* 404x194: \u5de6\u4fa7\u7ad6\u6392\u6807\u7b7e */\n.card[data-size=\"6x3\"] .wk{grid-template-columns:56px minmax(0,1fr);grid-template-rows:auto minmax(0,1fr) auto;\n  grid-template-areas:\"tabs hd\" \"tabs body\" \"tabs ft\";column-gap:8px;row-gap:5px;padding:8px 10px}\n.card[data-size=\"6x3\"] .tabs{flex-direction:column}\n.card[data-size=\"6x3\"] .tab{flex:1;height:auto;min-height:0}\n.card[data-size=\"6x3\"] .cnt{display:inline}\n.card[data-size=\"6x3\"] .wk.form{grid-template-columns:minmax(0,1fr) 112px;grid-template-rows:auto minmax(0,1fr);\n  grid-template-areas:\"hd hd\" \"body ft\"}\n.card[data-size=\"6x3\"] .wk.form .ft{flex-direction:column;flex-wrap:nowrap;align-content:flex-start}\n.card[data-size=\"6x3\"] .wk.form .btn,.card[data-size=\"6x3\"] .wk.form .btn.pri{flex:none;width:100%}\n.card[data-size=\"6x3\"] .wk.form .pair{grid-template-columns:minmax(0,1fr) minmax(0,1fr)}\n.card[data-size=\"6x3\"] .btn{height:30px}\n\n/* 194x404 */\n.card[data-size=\"3x6\"] .wk{padding:10px}\n\n/* 404x404 */\n.card[data-size=\"6x6\"] .wk{padding:14px;gap:8px;font-size:13.5px}\n.card[data-size=\"6x6\"] .strip{display:flex}\n.card[data-size=\"6x6\"] .tab{height:32px;font-size:13px}\n.card[data-size=\"6x6\"] .hd{min-height:32px}\n.card[data-size=\"6x6\"] .nb{width:32px;height:32px}\n.card[data-size=\"6x6\"] .lab{font-size:15px}\n.card[data-size=\"6x6\"] .btn{height:36px;font-size:13.5px}\n.card[data-size=\"6x6\"] .btn.sm{height:auto}\n.card[data-size=\"6x6\"] .in{height:36px}\n\n@media (prefers-reduced-motion:no-preference){\n  .btn,.tab,.row,.it{transition:background-color .15s,border-color .15s,opacity .15s}\n}\n";
var WD=['周一','周二','周三','周四','周五','周六','周日'];
var MAXB=120,MINB=30;
function p2(n){return (n<10?'0':'')+n}
function toMin(t){
  if(!/^\d{1,2}:\d{2}$/.test(t||''))return NaN;
  var a=t.split(':'),h=+a[0],m=+a[1];
  if(h>23||m>59)return NaN;
  return h*60+m;
}
function fromMin(n){return p2(Math.floor(n/60))+':'+p2(n%60)}
function parseD(s){var a=s.split('-');return new Date(+a[0],+a[1]-1,+a[2])}
function fmtDate(d){return d.getFullYear()+'-'+p2(d.getMonth()+1)+'-'+p2(d.getDate())}
function addD(s,n){var d=parseD(s);d.setDate(d.getDate()+n);return fmtDate(d)}
function wdOf(s){return (parseD(s).getDay()+6)%7}
function mondayOf(s){return addD(s,-wdOf(s))}
function md(s){var a=s.split('-');return (+a[1])+'/'+(+a[2])}
function validDate(s){return /^\d{4}-\d{2}-\d{2}$/.test(s||'')&&fmtDate(parseD(s))===s}
function dur(m){
  var h=Math.floor(m/60),r=m%60;
  if(!h)return r+'分钟';
  return r?h+'小时'+r+'分':h+'小时';
}
function nowMin(){var d=new Date();return d.getHours()*60+d.getMinutes()}
function norm(s){
  s=s||{};
  return {
    todos:Array.isArray(s.todos)?s.todos:[],
    meetings:Array.isArray(s.meetings)?s.meetings:[],
    avail:(s.avail&&typeof s.avail==='object')?s.avail:{},
    plans:(s.plans&&typeof s.plans==='object')?s.plans:{}
  };
}
function winsOf(av,wd){var w=av[wd];return Array.isArray(w)?w:[]}
function availMin(av,wd){
  var t=0;
  winsOf(av,wd).forEach(function(w){var a=toMin(w.start),b=toMin(w.end);if(b>a)t+=b-a});
  return t;
}
function ovl(a0,a1,b0,b1){return a0<b1&&b0<a1}
function cmpIt(a,b){
  if(a.date!==b.date)return a.date<b.date?-1:1;
  return toMin(a.start)-toMin(b.start);
}
function subIv(list,b0,b1){
  var out=[];
  list.forEach(function(iv){
    if(b1<=iv[0]||b0>=iv[1]){out.push(iv);return}
    if(b0>iv[0])out.push([iv[0],b0]);
    if(b1<iv[1])out.push([b1,iv[1]]);
  });
  return out;
}
function conflictsOf(it,n,items){
  var a0=toMin(it.start),a1=toMin(it.end),r=[];
  n.meetings.forEach(function(m){
    if(m.date===it.date&&ovl(a0,a1,toMin(m.start),toMin(m.end)))r.push('与会议「'+m.title+'」重叠');
  });
  items.forEach(function(o){
    if(o.id!==it.id&&o.date===it.date&&ovl(a0,a1,toMin(o.start),toMin(o.end)))r.push('与「'+o.title+'」重叠');
  });
  return r;
}
function inAvail(n,it){
  var a0=toMin(it.start),a1=toMin(it.end);
  return winsOf(n.avail,wdOf(it.date)).some(function(w){return toMin(w.start)<=a0&&a1<=toMin(w.end)});
}
function buildPlan(n,ws,kept,today,nm,uid){
  var days=[],i;
  for(i=0;i<7;i++){var dd=addD(ws,i);if(dd>=today)days.push(dd)}
  var free={};
  days.forEach(function(d){
    var iv=winsOf(n.avail,wdOf(d)).map(function(w){return [toMin(w.start),toMin(w.end)]}).filter(function(x){return x[1]>x[0]});
    if(d===today){
      var c=Math.ceil(nm/15)*15;
      iv=iv.map(function(x){return [Math.max(x[0],c),x[1]]}).filter(function(x){return x[1]>x[0]});
    }
    n.meetings.forEach(function(m){if(m.date===d)iv=subIv(iv,toMin(m.start),toMin(m.end))});
    kept.forEach(function(k){if(k.date===d)iv=subIv(iv,toMin(k.start),toMin(k.end))});
    iv.sort(function(a,b){return a[0]-b[0]});
    free[d]=iv;
  });
  var got={};
  kept.forEach(function(k){got[k.todoId]=(got[k.todoId]||0)+toMin(k.end)-toMin(k.start)});
  var list=[];
  n.todos.forEach(function(t){
    if(t.done)return;
    var rem=t.minutes-(got[t.id]||0);
    if(rem>0)list.push({t:t,rem:rem,used:{}});
  });
  list.sort(function(a,b){
    var da=a.t.due||'9999',db=b.t.due||'9999';
    if(da!==db)return da<db?-1:1;
    if((b.t.prio||0)!==(a.t.prio||0))return (b.t.prio||0)-(a.t.prio||0);
    return b.t.minutes-a.t.minutes;
  });
  function okDay(t,d){return !t.due||d<=t.due||t.due<days[0]}
  var items=[],go=true;
  while(go){
    go=false;
    list.forEach(function(x){
      if(x.rem<=0)return;
      var cand=days.filter(function(d){return okDay(x.t,d)});
      var order=cand.filter(function(d){return !x.used[d]}).concat(cand.filter(function(d){return x.used[d]}));
      var chunk=Math.min(x.rem,MAXB);
      if(x.rem>chunk&&x.rem-chunk<MINB)chunk=x.rem-MINB;
      for(var q=0;q<order.length;q++){
        var d=order[q],ivs=free[d],k=-1,j,len=chunk;
        for(j=0;j<ivs.length;j++){if(ivs[j][1]-ivs[j][0]>=chunk){k=j;break}}
        if(k<0){
          for(j=0;j<ivs.length;j++){if(ivs[j][1]-ivs[j][0]>=Math.min(MINB,x.rem)){k=j;break}}
          if(k<0)continue;
          len=ivs[k][1]-ivs[k][0];
          if(x.rem-len>0&&x.rem-len<MINB){len=x.rem-MINB;if(len<MINB)continue}
        }
        var s0=ivs[k][0];
        ivs[k][0]+=len;
        if(ivs[k][0]>=ivs[k][1])ivs.splice(k,1);
        x.rem-=len;x.used[d]=1;go=true;
        items.push({id:uid(),todoId:x.t.id,title:x.t.title,date:d,start:fromMin(s0),end:fromMin(s0+len),sel:true,status:'draft'});
        break;
      }
    });
  }
  var un=[];
  list.forEach(function(x){
    if(x.rem>0){
      var c=days.filter(function(d){return okDay(x.t,d)});
      un.push({todoId:x.t.id,title:x.t.title,minutes:x.rem,reason:c.length?'空闲时间不够':'截止日前没有可排的日子'});
    }
  });
  items.sort(cmpIt);
  return {items:items,unplaced:un};
}

function mount(ctx){
  const {root,el,state,ui,update,commit,redraw,uid,day,size}=ctx;
  var n=norm(state), today=day();
  if(!ui.tab)ui.tab='plan';
  if(!ui.ws)ui.ws=mondayOf(today);
  var ws=ui.ws, we=addD(ws,6);
  var SZ=String(size||root.getAttribute('data-size')||'');
  var narrow=SZ.charAt(0)==='3';
  var plan=n.plans[ws]||null;
  var items=plan?plan.items:[];
  var openTodos=n.todos.filter(function(t){return !t.done});
  var doneTodos=n.todos.filter(function(t){return t.done});
  var availDays=0,availTotal=0;
  for(var wi=0;wi<7;wi++){var am=availMin(n.avail,wi);if(am>0)availDays++;availTotal+=am}
  var weekMeets=n.meetings.filter(function(m){return m.date>=ws&&m.date<=we});
  var weekPast=we<today;
  var ready=openTodos.length>0&&availDays>0&&!weekPast;
  function conf(it){return conflictsOf(it,n,items)}
  var picks=items.filter(function(it){return it.status==='draft'&&it.sel&&!conf(it).length});

  function push(a,c){
    if(c==null||c===false)return;
    if(Array.isArray(c)){c.forEach(function(x){push(a,x)})}
    else a.push(typeof c==='number'?String(c):c);
  }
  function h(tag,attrs){
    var kids=[];
    for(var i=2;i<arguments.length;i++)push(kids,arguments[i]);
    return el.apply(null,[tag,attrs||{}].concat(kids));
  }
  function btn(label,fn,cls,dis){
    return h('button',{type:'button',class:'btn'+(cls?' '+cls:''),disabled:!!dis,onclick:fn},label);
  }
  function tag(t,cls){return h('span',{class:'tag'+(cls?' '+cls:'')},t)}
  function go(patch){
    Object.keys(patch).forEach(function(k){ui[k]=patch[k]});
    ui.err=null;
    redraw();
  }
  function fail(msg){ui.err=msg;redraw();return false}
  function done(extra){return Object.assign({},ui,{screen:null,draft:null,err:null,delAsk:false},extra||{})}
  function setPlans(s,fn){
    var m=norm(s),pl=Object.assign({},m.plans);
    Object.keys(pl).forEach(function(k){pl[k]=fn(pl[k],k)});
    return pl;
  }
  function patchPlan(fn){
    return update(function(s){
      var m=norm(s),p=m.plans[ws];
      if(!p)return s;
      var pl=Object.assign({},m.plans);
      pl[ws]=Object.assign({},p,fn(p));
      return Object.assign({},s,{plans:pl});
    });
  }
  function setWeek(w){ui.ws=w;ui.confirmRegen=false;ui.notice=null;ui.err=null;redraw()}

  /* ---------- 计划 ---------- */
  function togSel(id){
    patchPlan(function(p){return {items:p.items.map(function(i){return i.id===id?Object.assign({},i,{sel:!i.sel}):i})}});
  }
  function selAll(v){
    patchPlan(function(p){return {items:p.items.map(function(i){return i.status==='draft'?Object.assign({},i,{sel:v}):i})}});
  }
  function genPlan(){
    ui.confirmRegen=false;ui.notice=null;
    update(function(s){
      var m=norm(s),p=m.plans[ws];
      var kept=p?p.items.filter(function(i){return i.status==='confirmed'}):[];
      var r=buildPlan(m,ws,kept,day(),nowMin(),uid);
      var pl=Object.assign({},m.plans);
      pl[ws]={items:kept.concat(r.items).sort(cmpIt),unplaced:r.unplaced};
      return Object.assign({},s,{plans:pl});
    });
  }
  function rdyRow(label,text,tab,ok){
    return h('button',{type:'button',class:'row rdy',onclick:function(){go({tab:tab})}},
      h('span',{class:'mk'+(ok?' on':'')},ok?'✓':'○'),
      h('span',{class:'rl'},label),
      h('span',{class:'rt'},text));
  }
  function itemRow(it){
    var cf=conf(it),isC=it.status==='confirmed',mins=toMin(it.end)-toMin(it.start);
    return h('div',{class:'it'+(isC?' lock':'')+(cf.length?' bad':'')},
      isC?h('span',{class:'lk','aria-label':'已确认'},'✓')
         :h('input',{type:'checkbox',class:'ck',checked:!!it.sel,'aria-label':'选中 '+it.title,onchange:function(){togSel(it.id)}}),
      h('button',{type:'button',class:'itb',onclick:function(){openItem(it.id)}},
        h('span',{class:'tm'},it.start+'–'+it.end),
        h('span',{class:'tt'},it.title),
        h('span',{class:'sb'},dur(mins),
          isC?tag('已确认·待写入','ok'):null,
          cf.length?tag('！'+cf[0],'warn'):null,
          (!cf.length&&!inAvail(n,it))?tag('超出空闲时间'):null)));
  }
  function meetRow(m,edit){
    var inner=[h('span',{class:'tm'},m.start+'–'+m.end),h('span',{class:'tt'},m.title),
      h('span',{class:'sb'},edit?'点按修改':'会议 · 不会改动')];
    if(edit)return h('button',{type:'button',class:'row mrow',onclick:function(){openMeet(m.id)}},inner);
    return h('div',{class:'it mt'},h('span',{class:'lk','aria-label':'固定'},'▪'),h('div',{class:'itb'},inner));
  }
  function dayHead(d,i,extra){
    return h('div',{class:'dayh'+(d===today?' now':'')},
      h('b',{},WD[i]),h('span',{},md(d)),d===today?tag('今天'):null,extra?h('em',{},extra):null);
  }
  function strip(){
    var cols=[];
    for(var i=0;i<7;i++){
      var d=addD(ws,i),pm=0;
      items.forEach(function(it){if(it.date===d)pm+=toMin(it.end)-toMin(it.start)});
      var av=availMin(n.avail,i),pct=av>0?Math.min(100,Math.round(pm*100/av)):(pm>0?100:0);
      cols.push(h('div',{class:'sd'+(d===today?' now':'')},
        h('div',{class:'bar','aria-label':WD[i]+' 已排 '+dur(pm)},h('i',{style:'height:'+pct+'%'})),
        h('span',{class:'sdn'},WD[i].charAt(1)),
        h('span',{class:'sdm'},pm?(Math.round(pm/6)/10)+'h':'-')));
    }
    return h('div',{class:'strip'},cols);
  }
  function planTab(){
    var k=[];
    if(ui.notice)k.push(h('div',{class:'note'},h('span',{},ui.notice),btn('知道了',function(){go({notice:null})},'sm')));
    if(!plan){
      k.push(rdyRow('日历','读取未接入 · 手动录入会议 '+weekMeets.length+' 个','cal',weekMeets.length>0));
      k.push(rdyRow('待办',openTodos.length?openTodos.length+' 项待排 · 共 '+dur(openTodos.reduce(function(a,t){return a+t.minutes},0)):'还没有待办','todo',openTodos.length>0));
      k.push(rdyRow('空闲',availDays?'已设 '+availDays+' 天 · 每周共 '+dur(availTotal):'还没设置每天有空的时间','avail',availDays>0));
      k.push(h('p',{class:'hint'},weekPast?'这一周已经过去，不能再排。':'生成的是草案：先在这里改，确认后才会加入日历。现有会议不会被移动。'));
      return k;
    }
    var drafts=items.filter(function(i){return i.status==='draft'}),conf2=items.length-drafts.length;
    var tot=items.reduce(function(a,i){return a+toMin(i.end)-toMin(i.start)},0);
    k.push(h('div',{class:'sum'},h('span',{},'草案 '+drafts.length+' 段 · 共 '+dur(tot)+(conf2?' · 已确认 '+conf2:'')),
      drafts.length?h('button',{type:'button',class:'lnk',onclick:function(){selAll(picks.length<drafts.length)}},picks.length<drafts.length?'全选':'全不选'):null));
    if(SZ==='6x6')k.push(strip());
    var shown=0;
    for(var i=0;i<7;i++){
      var d=addD(ws,i);
      var its=items.filter(function(x){return x.date===d}).sort(cmpIt);
      var ms=n.meetings.filter(function(m){return m.date===d});
      if(!its.length&&!ms.length)continue;
      shown++;
      var rows=its.map(function(x){return {s:toMin(x.start),node:itemRow(x)}}).concat(ms.map(function(m){return {s:toMin(m.start),node:meetRow(m,false)}}));
      rows.sort(function(a,b){return a.s-b.s});
      k.push(dayHead(d,i),rows.map(function(r){return r.node}));
    }
    if(!shown)k.push(h('p',{class:'hint'},'这一周没有排进任何安排。'));
    if(plan.unplaced&&plan.unplaced.length){
      k.push(h('div',{class:'unp'},h('b',{},'还没排下 '+plan.unplaced.length+' 项'),
        plan.unplaced.map(function(u){return h('span',{class:'ur'},u.title+'：差 '+dur(u.minutes)+'（'+u.reason+'）')})));
    }
    return k;
  }
  function planFoot(){
    var f=[];
    if(!plan){
      f.push(btn(weekPast?'这一周已过去':'生成本周草案',genPlan,'pri',!ready));
      return f;
    }
    var hasDraft=items.some(function(i){return i.status==='draft'});
    if(ui.confirmRegen){
      f.push(h('div',{class:'err'},'重新排会覆盖草案里的修改，已确认的保留。'));
      f.push(btn('取消',function(){go({confirmRegen:false})}),btn('重新排',genPlan,'pri',!ready));
      return f;
    }
    f.push(btn(narrow?'重排':'重新排',function(){if(hasDraft){go({confirmRegen:true})}else genPlan()},'',!ready));
    f.push(btn((narrow?'确认加入':'确认并加入日历')+(picks.length?'（'+picks.length+'）':''),function(){go({screen:'confirm',notice:null})},'pri',!picks.length));
    return f;
  }


  /* ---------- 日历 ---------- */
