    var m=id?n.meetings.filter(function(x){return x.id===id})[0]:null;
    var dd=today>=ws&&today<=we?today:ws;
    go({screen:'meet',delAsk:false,draft:m?{id:m.id,title:m.title,date:m.date,start:m.start,end:m.end}:{title:'',date:dd,start:'',end:''}});
