  function calTab(){
    var k=[];
    k.push(h('div',{class:'ban'},
      h('div',{class:'bh'},tag('未接入','warn'),h('b',{},'日历读取')),
      h('p',{},ui.calMsg||'平台暂时读不到你的日历。请把已有会议手动录在下面：排计划会避开它们，也不会改动它们。'),
      btn('读取日历',function(){go({calMsg:'没有可用的日历读取接口，这次没有读取任何数据，你的日历也没有被改动。'})},'sm')));
    var shown=0;
