  /* ---------- 表单 ---------- */
  function fld(label,input){return h('label',{class:'fd'},h('span',{class:'lb'},label),input)}
  function inp(key,type,ph,extra){
    var a={class:'in',type:type,value:ui.draft[key]==null?'':String(ui.draft[key]),
      oninput:function(e){ui.draft[key]=e.target.value}};
