    go({screen:'item',delAsk:false,draft:{id:it.id,title:it.title,date:it.date,start:it.start,end:it.end,status:it.status}});
  }
  function upsert(list,rec){
    var f=false;
    var out=list.map(function(o){if(o.id===rec.id){f=true;return Object.assign({},o,rec)}return o});
    if(!f)out.push(rec);
    return out;
  }
  function todoForm(){
    var d=ui.draft;
    return [
      fld('名称',inp('title','text','要做的事',{onkeydown:enter})),
      fld('预计用时（分钟）',inp('minutes','number','例如 90',{min:'5',max:'1440',step:'5'})),
      h('div',{class:'chips'},[30,60,90,120,180].map(function(m){
        return h('button',{type:'button',class:'chip',onclick:function(){d.minutes=String(m);redraw()}},dur(m));
      })),
      fld('截止日期（可不填）',inp('due','date')),
      h('div',{class:'fd'},h('span',{class:'lb'},'优先级'),
        h('div',{class:'seg'},[0,1,2].map(function(v){
          return h('button',{type:'button',class:'sg'+(d.prio===v?' on':''),onclick:function(){d.prio=v;redraw()}},PR[v]);
        })))
    ];
