  function saveTodo(){
    var d=ui.draft,t=(d.title||'').trim(),m=Math.round(Number(d.minutes));
    if(!t)return fail('请填写待办名称');
    if(!(m>=5&&m<=1440))return fail('预计用时请填 5 到 1440 分钟');
    if(d.due&&!validDate(d.due))return fail('截止日期不正确');
    var id=d.id||uid(),rec={id:id,title:t,minutes:m,due:d.due||'',prio:d.prio==null?1:d.prio};
    return commit(function(s){
      var x=norm(s);
      var pl=setPlans(s,function(p){
        return Object.assign({},p,{items:p.items.map(function(i){return i.todoId===id&&i.status==='draft'?Object.assign({},i,{title:t}):i})});
      });
      var todos=upsert(x.todos,Object.assign({done:false},rec));
      return Object.assign({},s,{todos:todos,plans:pl});
    },done({tab:'todo'}));
  }
  function delTodo(){
    if(!ui.delAsk)return go({delAsk:true});
    var id=ui.draft.id;
    return commit(function(s){
      var x=norm(s);
      var pl=setPlans(s,function(p){
        return Object.assign({},p,{
          items:p.items.filter(function(i){return !(i.todoId===id&&i.status==='draft')}),
          unplaced:(p.unplaced||[]).filter(function(u){return u.todoId!==id})});
      });
      return Object.assign({},s,{todos:x.todos.filter(function(t){return t.id!==id}),plans:pl});
    },done({tab:'todo'}));
  }
