  function saveMeet(){
    var d=ui.draft,t=(d.title||'').trim();
    if(!t)return fail('请填写会议名称');
    if(!validDate(d.date))return fail('请选择日期');
    var a=toMin(d.start),b=toMin(d.end);
    if(isNaN(a)||isNaN(b))return fail('请填写开始和结束时间');
    if(b<=a)return fail('结束时间要晚于开始时间');
    var rec={id:d.id||uid(),title:t,date:d.date,start:fromMin(a),end:fromMin(b)};
    return commit(function(s){
      return Object.assign({},s,{meetings:upsert(norm(s).meetings,rec)});
    },done({tab:'cal',ws:mondayOf(d.date)}));
