    if(!ui.delAsk)return go({delAsk:true});
    var id=ui.draft.id;
    return commit(function(s){
      return Object.assign({},s,{meetings:norm(s).meetings.filter(function(m){return m.id!==id})});
    },done({tab:'cal'}));
