  function itemForm(){
    var d=ui.draft;
    return [
      h('div',{class:'it2'},h('b',{},d.title),d.status==='confirmed'?tag('已确认·待写入','ok'):tag('草案')),
      fld('日期（本周内）',inp('date','date','',{min:ws,max:we})),
