  function saveItem(){
    var d=ui.draft;
    if(!validDate(d.date)||d.date<ws||d.date>we)return fail('日期要在本周内（'+md(ws)+' 到 '+md(we)+'）');
    var a=toMin(d.start),b=toMin(d.end);
    if(isNaN(a)||isNaN(b))return fail('请填写开始和结束时间');
    if(b<=a)return fail('结束时间要晚于开始时间');
    var rec={id:d.id,title:d.title,date:d.date,start:fromMin(a),end:fromMin(b)};
    var cf=conflictsOf(rec,n,items);
    if(cf.length)return fail(cf[0]+'，请换个时间');
    return commit(function(s){
      var m=norm(s),p=m.plans[ws];
      if(!p)return s;
      var pl=Object.assign({},m.plans);
      pl[ws]=Object.assign({},p,{items:p.items.map(function(i){
        return i.id===rec.id?Object.assign({},i,{date:rec.date,start:rec.start,end:rec.end}):i;
      }).sort(cmpIt)});
      return Object.assign({},s,{plans:pl});
    },done());
  }
