      var m=norm(s),p=m.plans[ws];
      if(!p)return s;
      var pl=Object.assign({},m.plans);
      pl[ws]=Object.assign({},p,{items:p.items.filter(function(i){return i.id!==id})});
      return Object.assign({},s,{plans:pl});
