  function availForm(){
    var d=ui.draft;
    var k=[h('p',{class:'hint'},'填这一天有空的时间段，可以有多段，比如上午一段、晚上一段。全部留空表示这天没有空。')];
    d.wins.forEach(function(w,i){
      k.push(h('div',{class:'win'},
        h('div',{class:'pair'},
          h('input',{class:'in',type:'time',value:w.start||'','aria-label':'开始时间',oninput:function(e){w.start=e.target.value}}),
          h('input',{class:'in',type:'time',value:w.end||'','aria-label':'结束时间',oninput:function(e){w.end=e.target.value}})),
        btn('移除',function(){d.wins.splice(i,1);redraw()},'sm')));
    });
    k.push(btn('+ 再加一段',function(){d.wins.push({start:'',end:''});redraw()},'sm'));
    k.push(h('div',{class:'cp'},
      btn('保存并套用到周一至周五',function(){saveAvail([0,1,2,3,4])},'sm'),
      btn('保存并套用到每一天',function(){saveAvail([0,1,2,3,4,5,6])},'sm')));
    return k;
  }
  function saveAvail(targets){
    var d=ui.draft,wins=[];
    for(var i=0;i<d.wins.length;i++){
      var w=d.wins[i];
      if(!w.start&&!w.end)continue;
      var a=toMin(w.start),b=toMin(w.end);
      if(isNaN(a)||isNaN(b))return fail('每一段都要填完整的开始和结束时间');
      if(b<=a)return fail('每一段的结束时间要晚于开始时间');
      wins.push({start:fromMin(a),end:fromMin(b)});
    }
    wins.sort(function(x,y){return toMin(x.start)-toMin(y.start)});
    for(var j=1;j<wins.length;j++){if(toMin(wins[j].start)<toMin(wins[j-1].end))return fail('时间段不能互相重叠')}
    var tg=targets||[d.wd];
    return commit(function(s){
      var av=Object.assign({},norm(s).avail);
      tg.forEach(function(t){if(wins.length)av[t]=wins.map(function(x){return {start:x.start,end:x.end}});else delete av[t]});
      return Object.assign({},s,{avail:av});
    },done({tab:'avail'}));
  }
